export const getRequestMediaUploadUrlUrl = () => {
  return `/api/storage/uploads/request-url`;
};

/**
 * @summary Create a short-lived private R2 upload URL
 */
export const requestMediaUploadUrl = async (
  uploadUrlInput: UploadUrlInput,
  options?: Parameters<typeof customFetch>[1],
): Promise<UploadUrlResult> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<UploadUrlResult>(getRequestMediaUploadUrlUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(uploadUrlInput),
  });
};

